),
work_days AS (
  SELECT (DATE '2025-03-03' + gs) AS work_date FROM generate_series(0, 4) AS gs
)
INSERT INTO attendance (id, tenant_id, user_id, site_id, check_in, check_out, source, status, approved_by)
SELECT
  md5('crm-peru:attendance:' || ws.user_id::text || ':' || wd.work_date::text)::uuid,
  'a0000000-0000-4000-8000-000000000001'::uuid,
  ws.user_id,
  ws.site_id,
  wd.work_date + TIME '08:05:00',
  wd.work_date + TIME '17:10:00',
  'manual',
  'approved',
  ws.approver_user_id
FROM worker_site ws
CROSS JOIN work_days wd
ON CONFLICT DO NOTHING;

